$('#close').onclick=()=>{if(!editorDirty||confirm('Discard unsaved changes?')){if(typeof discardEditorDraft==='function')discardEditorDraft();$('#editor').close()}};$('#editor').addEventListener('cancel',e=>{if(editorDirty&&!confirm('Discard unsaved changes?'))e.preventDefault();else if(typeof discardEditorDraft==='function')discardEditorDraft()});$('#editor').addEventListener('close',()=>{editorGeneration++;editorDirty=false;attentionNavigation=null});window.addEventListener('beforeunload',e=>{if(editorDirty){e.preventDefault();e.returnValue=''}});$('#add').onclick=()=>openEditor(null);
$('#form').onsubmit=async e=>{e.preventDefault();if(editorSavePending||(typeof attentionNavigationPending!=='undefined'&&attentionNavigationPending))return;const nav=typeof attentionNavigation!=='undefined'?attentionNavigation:null,wantsNext=e.submitter?.id==='save-next';if(wantsNext&&(!nav||nav.index>=nav.rows.length-1))return;editorSavePending=true;$('#save-asset').disabled=true;$('#fields').inert=true;if(typeof updateAttentionNavigation==='function')updateAttentionNavigation();const editor=editing,generation=editorGeneration;const current=()=>editorGeneration===generation&&editing===editor;try{if(!editor.name?.trim()||!editor.family?.trim())throw Error('Asset name and family are required.');const payload=prepareAssetForSave(editor,editorDrafts);const saved=editor.id?await api('/api/assets/'+encodeURIComponent(editor.id),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({asset:payload,version:editor.version})}):await api('/api/assets',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const completedHere=current();if(completedHere){if(typeof discardEditorDraft==='function')discardEditorDraft();editorDirty=false;if(saved?.version!==undefined)editor.version=saved.version;if(wantsNext){const navigation={...nav,index:nav.index+1},item=navigation.rows[navigation.index];try{await openEditor(item.assetId,{inspectionType:item.inspectionType,issue:item.issue,attention:navigation.attention!==false,attentionNavigation:navigation})}catch(error){$('#edit-error').textContent='Saved, but the next entry could not be opened: '+error.message}}else $('#editor').close()}await load();renderAssets();if(typeof loadQuality==='function'&&!$('#quality').hidden)await loadQuality();if(completedHere&&editing===editor&&!$('#editor').open)message('Asset saved. Data-quality checks will reassess the saved values; manual verification remains optional.')}catch(err){if(current())$('#edit-error').textContent=err.message}finally{editorSavePending=false;$('#save-asset').disabled=false;$('#fields').inert=false;if(typeof updateAttentionNavigation==='function')updateAttentionNavigation()}};
let importFile=null, importInfo=null, importSelection=new Set(), importGeneration=0, importBusy=false;
let importReview={token:null,conflicts:[],decisions:new Map(),dirty:new Set(),partial:false};
function importSelectionNames(){return importInfo?.format==='legacy'?importInfo.sheets.filter(s=>importSelection.has(s.name)).map(s=>s.name):null}
function importResponseIsCurrent(generation,file){return generation===importGeneration&&file===importFile}
function invalidateImportPreview(){importGeneration++;previewToken=null;importBusy=false;importReview={token:null,conflicts:[],decisions:new Map(),dirty:new Set(),partial:false};$('#apply').hidden=true;$('#import-result').replaceChildren()}
function resetImportState(clearFile=false){
 invalidateImportPreview();
 if(clearFile){importFile=null;importInfo=null;importSelection.clear();$('#file').value='';$('#import-file-status').textContent=''}
 renderImportSheets();
}
function updateImportSelection(name,included){if(included)importSelection.add(name);else importSelection.delete(name);invalidateImportPreview();renderImportSheets()}
function renderImportSheets(){
 if(typeof renderImportProgress==='function')renderImportProgress();
 const box=$('#import-tabs'),list=$('#import-tab-list');list.replaceChildren();box.hidden=importInfo?.format!=='legacy';
 const legacy=importInfo?.format==='legacy',partial=legacy&&(importSelection.size<importInfo.sheets.length||importReview.partial);
 $('#import-mode').disabled=!!partial;if(partial)$('#import-mode').value='merge';
 $('#import-selection-help').textContent=partial?'Excluded tabs and skipped rows contribute no imported assets. Merge retains existing records. Replace is unavailable for partial imports.':'All tabs included. Reference-only tabs preserve cell values without creating assets.';
 $('#preview').disabled=importBusy||!importInfo||(legacy&&importSelection.size===0);
 if(!legacy)return;
 for(const sheet of importInfo.sheets){const label=el('label',null,'import-tab'),check=el('input');check.type='checkbox';check.checked=importSelection.has(sheet.name);check.onchange=()=>updateImportSelection(sheet.name,check.checked);label.append(check,el('span',sheet.name),el('small',sheet.role==='assets'?'Assets and inspections':sheet.role==='reference'?'Reference data only':'Unsupported · exclude to continue'));list.append(label)}
 $('#import-select-all').onclick=()=>{importSelection=new Set(importInfo.sheets.map(s=>s.name));invalidateImportPreview();renderImportSheets()};
 $('#import-deselect-all').onclick=()=>{importSelection.clear();invalidateImportPreview();renderImportSheets()};
 $('#import-tab-count').textContent=`${importSelection.size} of ${importInfo.sheets.length} tabs included`;
}
async function inspectImportFile(){
 invalidateImportPreview();importFile=$('#file').files[0]||null;importInfo=null;importSelection.clear();renderImportSheets();message('');
 $('#import-file-status').textContent='';if(!importFile)return;
 const file=importFile,generation=importGeneration;importBusy=true;$('#preview').disabled=true;$('#import-file-status').textContent='Reading workbook tabs…';
 try{const info=await api('/api/import/inspect',{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:await file.arrayBuffer()});if(!importResponseIsCurrent(generation,file))return;importInfo=info;importSelection=new Set(info.sheets.map(s=>s.name));$('#import-file-status').textContent=info.format==='legacy'?'Original workbook recognized. Choose tabs below, then preview.':'Cleaned workbook recognized. Its linked tables are imported together.';importBusy=false;renderImportSheets()}
 catch(err){if(importResponseIsCurrent(generation,file)){$('#import-file-status').textContent='';importBusy=false;message(err.message,true);renderImportSheets()}}
}
$('#file').onchange=inspectImportFile;
async function previewImportFile(){
 if(!importFile||!importInfo)return message('Select a workbook and wait for its tabs to load.',true);
 const selected=importSelectionNames();if(selected&&selected.length===0)return message('Include at least one workbook tab.',true);
 invalidateImportPreview();const file=importFile,generation=importGeneration;importBusy=true;renderImportSheets();
 try{const headers={'Content-Type':'application/octet-stream'};if(selected)headers['X-Import-Sheets']=JSON.stringify(selected);const result=await api('/api/import/preview',{method:'POST',headers,body:await file.arrayBuffer()});if(!importResponseIsCurrent(generation,file))return;renderImportPreview(result);message('')
 }catch(err){if(importResponseIsCurrent(generation,file))message(err.message,true)}
 finally{if(importResponseIsCurrent(generation,file)){importBusy=false;renderImportSheets()}}
}
