// Tabs only change presentation: the existing fields retain their values and handlers.
function setupEditorTabs(initial=0){
 const tabs=$('#editor-tabs');tabs.replaceChildren();
 const groups=[...$('#fields').children];
 const labels=['Overview','Inspections','Technical','Remarks & review','Source'];
 const category=g=>Number(g.dataset.editorSection);
 const available=labels.map((label,index)=>({label,index})).filter(({index})=>groups.some(g=>category(g)===index));
 function activate(index,focus=false){for(const g of groups)g.hidden=category(g)!==index;$('#fields').setAttribute('role','tabpanel');$('#fields').setAttribute('aria-labelledby','editor-tab-'+index);for(const b of tabs.children){const selected=Number(b.dataset.section)===index;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;if(selected&&focus)b.focus()}}
 for(const {label,index} of available){const b=el('button',label);b.type='button';b.dataset.section=index;if(groups.some(g=>category(g)===index&&g.querySelector('.recon-updated-field, .recon-pending-field')))b.append(el('span',' • Review','recon-tab-mark'));b.id='editor-tab-'+index;b.setAttribute('role','tab');b.setAttribute('aria-controls','fields');b.onclick=()=>activate(index);b.onkeydown=e=>{const keys=['ArrowLeft','ArrowRight','Home','End'];if(!keys.includes(e.key))return;e.preventDefault();const current=available.findIndex(x=>x.index===Number(tabs.querySelector('[aria-selected="true"]').dataset.section));const next=e.key==='Home'?0:e.key==='End'?available.length-1:(current+(e.key==='ArrowRight'?1:-1)+available.length)%available.length;activate(available[next].index,true)};tabs.append(b)}
 activate(initial);
}
$('#reset-filters').onclick=()=>{onlyRecentRecon=false;onlyConfirmedRecon=false;for(const id of ['search','sheet','family','service','due-filter','review-filter','group-assets'])$('#'+id).value='';$('#status').value='active';assetPage=1;renderAssets()};

function prepareAssetForSave(asset,drafts){
 const payload=structuredClone(asset);
 payload.technical_details=(payload.technical_details||[]).filter(t=>!drafts.has(t.field_id)||String(t.field_label||'').trim()||String(t.value??'').trim());
 payload.notes=(payload.notes||[]).filter(n=>!drafts.has(n.note_id)||String(n.note_text||'').trim());
 for(const t of payload.technical_details){if(drafts.has(t.field_id)&&!String(t.field_label||'').trim())throw Error('Enter a field name for each new technical value.');}
 return payload;
}

function assetDisplayName(a){
 const name=String(a.name||'').trim();
 if(name&&name.toLowerCase()!=='(unnamed asset)')return name;
 return [a.tag_original,a.asset_number_original,a.oracle_description].map(v=>String(v||'').trim()).find(v=>v&&!['na','n/a','none','-'].includes(v.toLowerCase()))||'Unnamed asset';
}

function selectedAssetRows(records,ids){return records.filter(a=>ids.has(a.id))}
function setVisibleAssetSelection(checked,rows=visibleAssetRows()){for(const asset of rows){if(checked)selectedAssets.add(asset.id);else selectedAssets.delete(asset.id)}}
function updateSelectionBar(){const visible=visibleAssetRows();const selected=visible.filter(a=>selectedAssets.has(a.id)).length;const check=$('#select-visible');check.checked=visible.length>0&&selected===visible.length;check.indeterminate=selected>0&&selected<visible.length;$('#selection-count').textContent=`${selectedAssets.size} selected`;$('#selection-bar').hidden=selectedAssets.size===0;$('#verify-selected').disabled=selectedAssets.size===0;}

