function updateBackupSelectionUI(){const names=savedBackups.map(backup=>backup.filename),selected=names.filter(name=>selectedBackupNames.has(name)).length,selectAll=$('#backup-select-all');$('#backup-selection-count').textContent=`${selected} selected`;selectAll.checked=names.length>0&&selected===names.length;selectAll.indeterminate=selected>0&&selected<names.length;$('#delete-selected-backups').disabled=selected===0}
function setSavedBackupSelection(filename,checked){if(checked)selectedBackupNames.add(filename);else selectedBackupNames.delete(filename);updateBackupSelectionUI()}
