async function deleteSelectedBackups(){const filenames=savedBackups.map(backup=>backup.filename).filter(filename=>selectedBackupNames.has(filename));if(!filenames.length){updateBackupSelectionUI();return}const prompt=`Permanently delete ${filenames.length} selected saved backup${filenames.length===1?'':'s'}?\n\n${filenames.join('\n')}\n\nThis cannot be undone. Recovery packages, snapshots, source archives, and the active database are not affected.`;if(!confirm(prompt))return;const button=$('#delete-selected-backups');button.disabled=true;try{const result=await api('/api/backups/delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({filenames})});selectedBackupNames.clear();await loadBackups();if(typeof loadBackupStatus==='function')await loadBackupStatus();const deleted=(result.deleted||[]).length,failed=result.failed||[];message(`Deleted ${deleted} backup${deleted===1?'':'s'}.`+(failed.length?` ${failed.length} could not be deleted: ${failed.map(item=>item.filename+': '+item.error).join('; ')}`:''),failed.length>0)}catch(error){message(error.message,true)}finally{updateBackupSelectionUI()}}
function setupBackupSelection(){$('#backup-select-all').onchange=event=>setAllSavedBackupSelection(event.target.checked);$('#delete-selected-backups').onclick=deleteSelectedBackups}
setupBackupSelection();
async function loadBackups(){const container=$('#backup-list');try{const backups=await api('/api/backups');savedBackups=backups;const names=new Set(backups.map(backup=>backup.filename));selectedBackupNames=new Set([...selectedBackupNames].filter(name=>names.has(name)));container.replaceChildren();if(!backups.length)container.append(el('p','No backups yet.'));for(const backup of backups){const row=el('div',null,'backup-row'),choice=el('label',null,'backup-choice'),check=el('input');check.type='checkbox';check.checked=selectedBackupNames.has(backup.filename);check.dataset.backupName=backup.filename;check.setAttribute('aria-label','Select backup '+backup.filename);check.onchange=()=>setSavedBackupSelection(backup.filename,check.checked);choice.append(check);const info=el('div');info.append(el('strong',backup.filename),el('small',`${new Date(backup.modified).toLocaleString()} · ${(backup.size/1024/1024).toFixed(2)} MB`));const button=el('button','Restore','secondary');button.onclick=async()=>{if(!confirm(`Restore ${backup.filename}? Current data will be replaced after a safety backup is created.`))return;button.disabled=true;try{const result=await api('/api/backups/restore',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({filename:backup.filename})});selectedAssets.clear();resetImportState();await load();await loadBackups();message('Backup restored. Safety backup saved: '+result.safety_backup)}catch(err){message(err.message,true)}finally{button.disabled=false}};row.append(choice,info,button);container.append(row)}updateBackupSelectionUI()}catch(err){savedBackups=[];selectedBackupNames.clear();container.replaceChildren(el('p',err.message,'error'));updateBackupSelectionUI()}}
$('#refresh-backups').onclick=loadBackups;

// Import preview and duplicate review share this script to avoid server-version loading mismatches.

function updateImportDecision(key,value){
 if(importBusy)return;
 if(!importReview.conflicts.some(row=>row.row_key===key))return;
 const decision={row_key:key,action:value.startsWith('match:')?'match':value||'review'};
 if(decision.action==='match')decision.asset_id=value.slice(6);
 importReview.decisions.set(key,decision);importReview.dirty.add(key);
 importGeneration++;previewToken=null;$('#apply').hidden=true;
 if(decision.action==='skip')importReview.partial=true;
 $('#import-resolve').disabled=false;
 $('#import-resolution-status').textContent='Choices changed. Update the preview to check them before importing.';
 renderImportSheets();
}

function importEvidence(parent,asset,inspections,notes){
 const fields=el('dl',null,'import-evidence');
 for(const [label,key] of [['Asset number','asset_number_original'],['Tag','tag_original'],['Service status','service_status_original'],['Report number','source_sequence'],['Group','source_group'],['Location','location_from'],['Unit / destination','unit_or_location_to'],['Package','pack_original'],['Oracle description','oracle_description']]){
  const value=asset[key];if(value===undefined||value===null||value==='')continue;
  fields.append(el('dt',label),el('dd',value));
 }
 parent.append(fields);
 for(const inspection of inspections||[])parent.append(el('p',`${inspection.inspection_type}: last ${inspection.last_inspection_month||inspection.last_original||'not supplied'} · next ${inspection.next_inspection_month||inspection.next_original||'not supplied'}`,'import-inspection'));
 if((notes||[]).length){const details=el('details');details.append(el('summary',`Notes and actions (${notes.length})`));for(const note of notes)details.append(el('p',`${note.note_type||'Note'}: ${note.note_text||''}`,'import-source-note'));parent.append(details)}
}

function renderImportConflicts(out,result){
 const conflicts=result.conflicts||[];if(!conflicts.length)return;
 const section=el('div',null,'import-conflict-review');
 section.append(el('h2','Resolve duplicate and matching conflicts'),el('p','For each incoming row, choose a separate asset, skip the repeated row, or select the existing asset it should update. Skipping leaves existing records untouched. Verified master values are retained when incoming values differ. Differences remain in Data quality for review.'));
 const status=el('p',result.unresolved_count?`${result.unresolved_count} rows still need a decision. Choose actions below, then update the preview.`:'All identity decisions checked. Review the totals and record changes before importing.');status.id='import-resolution-status';status.setAttribute('role','status');section.append(status);
 for(const row of conflicts){
  const card=el('article',null,'import-conflict-card');card.classList.toggle('import-conflict-resolved',!!row.resolved);
  card.append(el('h3',`${row.source_sheet} · Excel row ${row.source_row}`),el('strong',row.asset.name));
  for(const reason of row.reasons)card.append(el('p',reason,'muted'));
  importEvidence(card,row.asset,row.inspections,row.notes);
  const label=el('label',`How should ${row.source_sheet} row ${row.source_row} be imported?`),select=el('select');
  select.setAttribute('aria-label',`Import decision for ${row.source_sheet} row ${row.source_row}`);select.disabled=importBusy;
  for(const [value,text] of [['','Choose an action…'],['separate','Import as a separate asset'],['skip','Skip this incoming row']]){const option=el('option',text);option.value=value;select.append(option)}
  for(const candidate of row.candidates){const option=el('option',`Update existing: ${candidate.name} · source row ${candidate.source_row||'—'} · ${candidate.id}`);option.value='match:'+candidate.id;select.append(option)}
  const decision=importReview.decisions.get(row.row_key);select.value=decision?.action==='match'?'match:'+decision.asset_id:decision?.action==='review'?'':decision?.action||'';
  select.onchange=()=>updateImportDecision(row.row_key,select.value);label.append(select);card.append(label);
  if(row.candidates.length){const existing=el('details',null,'import-existing-matches');existing.append(el('summary',`Compare ${row.candidates.length} possible existing ${row.candidates.length===1?'asset':'assets'}`));
   for(const candidate of row.candidates){const record=el('div',null,'import-existing-record');record.append(el('h4',candidate.name),el('p',`${candidate.id} · ${candidate.source_sheet} · source row ${candidate.source_row||'—'}`));importEvidence(record,candidate,candidate.inspections,candidate.notes);existing.append(record)}card.append(existing)}
  section.append(card);
 }
 const button=el('button','Update preview');button.type='button';button.id='import-resolve';button.disabled=true;button.onclick=resolveImportPreview;section.append(button);out.append(section);
}

function renderImportPreview(result){
 if(result.format==='legacy'&&!Array.isArray(result.conflicts))throw Error('The running app server needs restarting for duplicate review. Close the app terminal, start Inspection App again, and reload this page.');
 importBusy=false;
 previewToken=result.token;
 importReview={token:result.token,conflicts:result.conflicts||[],decisions:new Map(),dirty:new Set(),partial:!!result.partial};
 for(const row of importReview.conflicts)if(row.decision)importReview.decisions.set(row.row_key,{row_key:row.row_key,...row.decision});
 const out=$('#import-result');out.replaceChildren(el('p',`${result.counts.Assets} assets · ${result.counts['Inspection Plan']} inspections · ${result.additions} new · ${result.updates} matching records reviewed for update · ${result.retained} existing records absent from import (retained in merge)`));
 if(result.format==='legacy'){
  out.append(el('p',`Original workbook · ${result.included_sheets.length} tabs included · ${result.excluded_sheets.length} excluded`));
  if(result.excluded_sheets.length)out.append(el('p','Excluded tabs: '+result.excluded_sheets.join(', ')));
  if(result.skipped_count)out.append(el('p',`${result.skipped_count} incoming rows skipped. Existing records are retained; merge mode is required.`));
  if(result.remembered_count)out.append(el('p',`Reused ${result.remembered_count} saved identity decisions for unchanged source rows. You can review or change them below.`,'info'));
 }
 if(result.digest){const archive=el('a','Download the exact archived source workbook');archive.href='/api/source/'+result.digest;archive.download='source-'+result.digest.slice(0,12)+'.xlsx';out.append(archive)}
 for(const warning of result.warnings||[])out.append(el('p',warning,'info'));
 for(const error of result.errors)out.append(el('p',error,'error'));
 renderImportConflicts(out,result);
 if(result.format==='legacy'){
  const sheets=el('details');sheets.append(el('summary','Included tabs and review items'));
  for(const sheet of result.sheet_summary){sheets.append(el('p',sheet.role==='reference'?`${sheet.name}: reference cells only`:`${sheet.name}: ${sheet.assets} extracted assets · ${sheet.inspections} inspection entries (before skipped rows)`));if(sheet.populated_rows!==undefined)sheets.append(el('p',`${sheet.populated_rows} populated rows accounted for. ${(sheet.unclassified_rows||[]).length} rows retained without asset classification.`));if(sheet.unclassified_rows?.length)sheets.append(el('p',`Check possible notes or missed assets in ${sheet.name}, rows ${sheet.unclassified_rows.join(', ')}. Their source values are preserved; they have not been silently treated as equipment.`,'error'))}
  sheets.append(el('p',`${result.counts['Review Items']} date/status review items. These are separate from identity decisions and can be checked after import. Workbook images, embedded objects and formatting are not imported; keep the original file.`));out.append(sheets);
 }
 const changed=result.comparison.filter(row=>row.status==='changed'),added=result.comparison.filter(row=>row.status==='new');
 const summary=el('details',null,'comparison');summary.append(el('summary',`Compare records · ${changed.length} with shown differences · ${added.length} new`),el('p','Shows current and incoming values, including notes and technical details. Verified master values win over incoming differences; missing linked rows are retained. Review remaining differences before applying.'));
 for(const item of changed){const row=el('div',null,'comparison-row');row.append(el('strong',`${item.name} · ${item.id}`));for(const change of item.changes)row.append(el('p',`${change.field}: previous source ${change.previous_source===null||change.previous_source===undefined?'not recorded':change.previous_source||'Blank'} · current master ${change.current||'Blank'} · incoming ${change.incoming||'Blank'}`));summary.append(row)}
 for(const item of added)summary.append(el('p',`New: ${item.name} · ${item.id}`));out.append(summary);
 const needsCoverage=(result.sheet_summary||[]).some(s=>s.unclassified_rows?.length);$('#apply').disabled=needsCoverage;if(needsCoverage){const label=el('label'),check=el('input');check.type='checkbox';check.id='import-coverage-ack';check.onchange=()=>{$('#apply').disabled=!check.checked};label.append(check,el('span','I reviewed the rows not classified as assets and accept this extraction coverage. Original values remain archived.'));out.append(label)}
 $('#apply').hidden=!!result.errors.length;renderImportSheets();
}

async function resolveImportPreview(){
 if(importBusy||!importReview.token||!importReview.dirty.size)return;
 const resolutions=[...importReview.dirty].map(key=>importReview.decisions.get(key));
 const base=importReview.token,generation=++importGeneration,file=importFile;
 previewToken=null;$('#apply').hidden=true;importBusy=true;$('#import-resolve').disabled=true;
 $('#import-resolution-status').textContent='Checking your choices…';
 for(const input of document.querySelectorAll('.import-conflict-card select'))input.disabled=true;
 renderImportSheets();
 try{
  const result=await api('/api/import/resolve',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:base,resolutions})});
  if(!importResponseIsCurrent(generation,file))return;
  importBusy=false;renderImportPreview(result);message('');
 }catch(error){
  if(importResponseIsCurrent(generation,file)){
   $('#import-resolution-status').textContent=error.message;message(error.message,true);importBusy=false;
   $('#import-resolve').disabled=false;for(const input of document.querySelectorAll('.import-conflict-card select'))input.disabled=false;
  }
 }finally{if(importResponseIsCurrent(generation,file)){importBusy=false;renderImportSheets()}}
}

let reviewRefreshTimer=null,reviewRefreshGeneration=0;
function reviewPreviewPayload(asset){return {id:asset.id||'draft',name:asset.name,family:asset.family,record_status:asset.record_status,inspections:asset.inspections||[],review_items:asset.review_items||[]}}
function applyReviewPreview(asset,preview){
 for(const inspection of asset.inspections||[]){const current=(preview.inspections||[]).find(i=>i.inspection_type===inspection.inspection_type);if(current){inspection.review_status=current.review_status;inspection.review_reason=current.review_reason;inspection.review_summary_generated=current.review_summary_generated}}
 for(const [index,item] of (asset.review_items||[]).entries()){if(preview.review_items?.[index])item.review_status=preview.review_items[index].review_status}
}
function scheduleReviewRefresh(){
 if(typeof editing==='undefined'||!editing)return;
 const generation=++reviewRefreshGeneration;clearTimeout(reviewRefreshTimer);
 reviewRefreshTimer=setTimeout(async()=>{
  const asset=editing,payload=reviewPreviewPayload(asset),before=JSON.stringify(payload);
  try{const preview=await api('/api/assets/review-preview',{method:'POST',headers:{'Content-Type':'application/json'},body:before});
   if(generation!==reviewRefreshGeneration||editing!==asset||JSON.stringify(reviewPreviewPayload(asset))!==before)return;
   applyReviewPreview(asset,preview);
   for(const comment of document.querySelectorAll('[data-review-rule]')){if(['ambiguous-date','chronology','missing-schedule','source-review','source-review-item'].includes(comment.dataset.reviewRule))comment.hidden=!(preview.review_findings||[]).some(f=>f.rule_id===comment.dataset.reviewRule&&f.field===comment.dataset.reviewField)}
   for(const notice of document.querySelectorAll('[data-inspection-review]')){const inspection=asset.inspections.find(i=>i.inspection_type===notice.dataset.inspectionReview);notice.hidden=inspection?.review_status!=='Review';for(const input of notice.querySelectorAll('input,select,textarea'))input.disabled=notice.hidden;if(!notice.hidden){const comment=notice.querySelector('p.error');if(comment)comment.textContent='Needs review: '+inspection.review_reason}}
   for(const control of document.querySelectorAll('[data-review-index]')){control.hidden=asset.review_items[Number(control.dataset.reviewIndex)]?.review_status!=='Review';for(const input of control.querySelectorAll('input,select,textarea'))input.disabled=control.hidden}
   for(const group of document.querySelectorAll('[data-review-items-group]')){const empty=!(asset.review_items||[]).some(item=>item.review_status==='Review');for(const child of group.children)child.hidden=empty;}
  }catch(error){/* Incomplete draft dates remain editable; save validates and reconciles. */}
 },200);
}
